const updateUserHNRObligation = `-- name: UpdateUserHNRObligation :execrows
UPDATE traffic.user_hnr_obligations
SET
    state = $1::text,
    seeded_seconds = $2::bigint,
    raw_uploaded = $3::bigint,
    raw_ratio_basis_points = $4::bigint,
    satisfied_by = $5::text,
    satisfied_at = $6::timestamptz,
    version = $7::bigint,
    occurred_at = $8::timestamptz,
    applied_at = $9::timestamptz
WHERE obligation_id = $10::uuid
  AND version = $11::bigint
  AND state = 'tracking'
`

type UpdateUserHNRObligationParams struct {
	State               string
	SeededSeconds       int64
	RawUploaded         int64
	RawRatioBasisPoints int64
	SatisfiedBy         pgtype.Text
	SatisfiedAt         pgtype.Timestamptz
	NewVersion          int64
	OccurredAt          pgtype.Timestamptz
	AppliedAt           pgtype.Timestamptz
	ObligationID        uuid.UUID
	ExpectedVersion     int64
}

func (q *Queries) UpdateUserHNRObligation(ctx context.Context, arg UpdateUserHNRObligationParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateUserHNRObligation,
		arg.State,
		arg.SeededSeconds,
		arg.RawUploaded,
		arg.RawRatioBasisPoints,
		arg.SatisfiedBy,
		arg.SatisfiedAt,
		arg.NewVersion,
		arg.OccurredAt,
		arg.AppliedAt,
		arg.ObligationID,
		arg.ExpectedVersion,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const upsertUserTorrentTrafficTotals = `-- name: UpsertUserTorrentTrafficTotals :exec
INSERT INTO traffic.user_torrent_totals (
    user_id,
    torrent_id,
    raw_uploaded,
    raw_downloaded,
    credited_uploaded,
    charged_downloaded,
    entry_count,
    version,
    last_occurred_at,
    updated_at
) VALUES (
    $1::uuid,
    $2::bigint,
    $3::bigint,
    $4::bigint,
    $5::bigint,
    $6::bigint,
    1,
    1,
    $7::timestamptz,
    $8::timestamptz
)
ON CONFLICT (user_id, torrent_id) DO UPDATE SET
    raw_uploaded = traffic.user_torrent_totals.raw_uploaded + EXCLUDED.raw_uploaded,
    raw_downloaded = traffic.user_torrent_totals.raw_downloaded + EXCLUDED.raw_downloaded,
    credited_uploaded = traffic.user_torrent_totals.credited_uploaded + EXCLUDED.credited_uploaded,
    charged_downloaded = traffic.user_torrent_totals.charged_downloaded + EXCLUDED.charged_downloaded,
    entry_count = traffic.user_torrent_totals.entry_count + 1,
    version = traffic.user_torrent_totals.version + 1,
    last_occurred_at = GREATEST(traffic.user_torrent_totals.last_occurred_at, EXCLUDED.last_occurred_at),
    updated_at = EXCLUDED.updated_at
`

type UpsertUserTorrentTrafficTotalsParams struct {
	UserID            uuid.UUID
	TorrentID         int64
	RawUploaded       int64
	RawDownloaded     int64
	CreditedUploaded  int64
	ChargedDownloaded int64
	OccurredAt        pgtype.Timestamptz
	UpdatedAt         pgtype.Timestamptz
}

func (q *Queries) UpsertUserTorrentTrafficTotals(ctx context.Context, arg UpsertUserTorrentTrafficTotalsParams) error {
	_, err := q.db.Exec(ctx, upsertUserTorrentTrafficTotals,
		arg.UserID,
		arg.TorrentID,
		arg.RawUploaded,
		arg.RawDownloaded,
		arg.CreditedUploaded,
		arg.ChargedDownloaded,
		arg.OccurredAt,
		arg.UpdatedAt,
	)
	return err
}

